// Coordination math: reliability multiplies, context adds (plain JS)
function teamReliability(accs) { return accs.reduce((p, a) => p * a, 1); }
function contextBill(perAgent, n, shared) { return shared + perAgent * n; }
// teamReliability([0.95, 0.95, 0.95]) ≈ 0.857: three 95s ≈ 86%
// Lesson: each handoff must EARN its error share via specialization gains.

