function decide(components) {
  return components.map((c) => {
    const build = c.moat * 2 - c.maintenance;
    const buy = 5 - c.maintenance;
    return { name: c.name, decision: build > buy ? 'build' : 'buy' };
  });
}
const parts = [
  { name: 'graph-exec', moat: 1, maintenance: 4 },
  { name: 'memory-policy', moat: 5, maintenance: 2 },
  { name: 'gold-eval', moat: 5, maintenance: 2 },
  { name: 'vector-engine', moat: 1, maintenance: 4 },
];
for (const d of decide(parts)) console.log(d.name + ' -> ' + d.decision);

